proxy := &httputil.ReverseProxy{
	Rewrite: func(r *httputil.ProxyRequest) {
		r.SetURL(backend)                            // routing from config
		r.SetXForwarded()
		r.Out.Header.Set("x-tenant", tenant(r.In))  // policy
	},
	Transport: pool,                                 // reuse, dial timeouts
	ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
		http.Error(w, "upstream unavailable", http.StatusBadGateway)
	},
}
http.Handle("/svc/", proxy)

func Policy(ctx context.Context, req any, info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler) (any, error) {
	start := time.Now()
	resp, err := handler(ctx, req)         // delegate: the real service
	metrics.Observe(info.FullMethod, time.Since(start), err)
	return resp, err                       // same contract
}

srv := grpc.NewServer(grpc.ChainUnaryInterceptor(Policy, Auth, RateLimit))
